</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

using ull = unsigned long long;

const int MAXN = 250010;

int n, k, p, lim;
int pc[MAXN];
ull fact[MAXN], invfact[MAXN], dp[26][MAXN];

namespace fast_input {
    const int BUFSIZE = 1 << 20;
    char buffer[BUFSIZE];
    int pos = 0, size = 0;

    inline int get_char() {
        if (pos == size) {
            size = (int)fread(buffer, 1, BUFSIZE, stdin);
            pos = 0;
            if (size == 0) return EOF;
        }
        return buffer[pos++];
    }

    template <class T>
    inline void read(T &x) {
        int c = get_char();
        while (c != EOF && (c < '0' || c > '9') && c != '-') c = get_char();
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = get_char();
        }
        x = 0;
        while (c >= '0' && c <= '9') {
            x = x * 10 + (c - '0');
            c = get_char();
        }
        x *= sign;
    }
}

ull mod_pow(ull base, int expo) {
    ull res = 1;
    while (expo > 0) {
        if (expo & 1) res = res * base % p;
        base = base * base % p;
        expo >>= 1;
    }
    return res;
}

ull comb(int N, int M) {
    return fact[N] * invfact[M] % p * invfact[N - M] % p;
}

int main() {
#ifndef ONLINE_JUDGE
    freopen("255x.in", "r", stdin);
    freopen("255x.out", "w", stdout);
#endif

    fast_input::read(n);
    fast_input::read(k);
    fast_input::read(p);

    for (int i = 1; i <= n; ++i) pc[i] = pc[i >> 1] + (i & 1);

    ull powv = mod_pow(k, n);
    if (n & 1) {
        printf("%d\n", powv);
        return 0;
    }

    lim = min(k, pc[n]);

    fact[0] = 1;
    for (int i = 1; i <= n; ++i) fact[i] = fact[i - 1] * i % p;

    invfact[n] = mod_pow(fact[n], p - 2);
    for (int i = n; i >= 1; --i) invfact[i - 1] = invfact[i] * i % p;

    vector<int> masks;
    for (int s = n;; s = (s - 1) & n) {
        masks.push_back(s);
        if (s == 0) break;
    }

    for (int s : masks) dp[1][s] = (pc[s] >= 1) ? invfact[s] : 0;

    for (int K = 2; K <= lim; ++K) {
        for (int s : masks) {
            if (pc[s] < K) {
                dp[K][s] = 0;
                continue;
            }

            ull cur = 0;
            int cnt = 0;
            for (int sub = (s - 1) & s; sub; sub = (sub - 1) & s) {
                if (pc[sub] >= K - 1) {
                    cur += dp[K - 1][sub] * invfact[s ^ sub];
                    if (++cnt == 18) {
                        cnt = 0;
                        cur %= p;
                    }
                }
            }
            dp[K][s] = cur % p;
        }
    }

    ull total = 0;
    for (int i = lim; i >= 1; --i) total += comb(k, i) * dp[i][n];

    ull ans = (powv - total % p * fact[n] % p + p) % p;
    printf("%lld\n", ans);
    return 0;
}
